源码
Main.sol
以下是智能合约代码的逐段解析，按功能模块分类说明：

1. 患者信息管理结构体定义struct Sick &#123;    address accountAddress; // 患者钱包地址    string name;            // 姓名    string sex;             // 性别    uint256 age;            // 年龄    uint256 id;             // 身份证号(主键)&#125;

数据存储mapping(uint256 =&gt; Sick) public sicks;  // 身份证号→患者信息的映射uint256[] public sickIds;               // 所有患者身份证号列表

核心功能// 创建患者档案 (需校验参数有效性)function createSick(...) public &#123;    // 参数校验...    sicks[identityNumber] = Sick(...);  // 存储信息    sickIds.push(identityNumber);       // 记录ID    emit SickCreated(...);              // 触发事件&#125;// 按身份证查询患者function getSickByIdentityNumber(...) public view returns (...) &#123;    require(sick.accountAddress != address(0)); // 校验存在性    return (sick.accountAddress, ...);&#125;// 按钱包地址查询患者function getSickByAccountAddress(...) public view returns (...) &#123;    uint256 sickID = findSickIDByAccountAddress(accountAddr); // 内部遍历查找    return (sick.name, ...);&#125;// 辅助函数：地址→ID映射function findSickIDByAccountAddress(...) internal view returns (...) &#123;    for (uint256 i = 0; i &lt; sickIds.length; i++) &#123;        if (sicks[sickID].accountAddress == accountAddr) return sickID;    &#125;    return 0;&#125;// 检查患者是否存在function isSickExist(uint256 sickID) public view returns (bool) &#123;    return sicks[sickID].accountAddress != address(0);&#125;// 获取所有患者ID列表function getSicksList() public view returns (uint256[] memory) &#123;    return sickIds;&#125;


2. 预约挂号系统结构体定义struct Appointment &#123;    string hospitalName; // 医院名称    string department;   // 科室名称&#125;

数据存储mapping(uint256 =&gt; Appointment) public sickAppointment; // 患者ID→预约信息

核心功能// 创建预约function createAppointment(...) public &#123;    require(isSickExist(sickID));          // 患者必须存在    sickAppointment[sickID] = Appointment(...); // 存储预约    emit AppointmentCreated(...);           // 触发事件&#125;// 查询预约function getSickAppointment(...) public view returns (...) &#123;    require(bytes(appointment.hospitalName).length &gt; 0); // 校验存在性    return (appointment.hospitalName, ...);&#125;// 删除预约function deleteSickAppointment(uint256 sickID) public &#123;    delete sickAppointment[sickID];  // 清除预约记录&#125;


3. 电子病历管理结构体定义struct MedicalRecord &#123;    uint256 sickID;               // 患者ID    string hospitalName;          // 医院    string department;            // 科室    string doctorName;            // 医生姓名    string registrationInfo;      // 挂号信息    string pastMedicalHistory;    // 既往病史    string currentMedicalHistory; // 现病史    string isFilled;              // 是否完成(&quot;Yes&quot;/&quot;No&quot;)&#125;

数据存储mapping(uint256 =&gt; MedicalRecord) public sickMedicalRecords; // 患者ID→病历

核心功能// 创建空白病历function createMedicalRecord(...) public &#123;    sickMedicalRecords[sickID] = MedicalRecord(...);    emit MedicalRecordCreated(...);&#125;// 授权医生访问病历function authorizeDoctor(...) public &#123;    if (病历不存在) createMedicalRecord(...); // 自动创建空病历    sickMedicalRecords[sickID].doctorName = doctorName; // 设置医生&#125;// 更新病历内容function updateMedicalRecord(...) public &#123;    medicalRecord.hospitalName = hospitalName;    medicalRecord.pastMedicalHistory = pastMedicalHistory; // 更新病史等    emit MedicalRecordUpdated(...);&#125;// 查询完整病历function getMedicalRecordByIdentityNumber(...) public view returns (...) &#123;    return (medicalRecord.hospitalName, ...); // 返回所有病历字段&#125;// 查询特定科室的既往病史function getPastMedicalHistory(...) public view returns (...) &#123;    require(keccak256(科室)==keccak256(目标科室)); // 严格科室匹配    return medicalRecord.pastMedicalHistory;&#125;// 标记病历完成状态function endMedicalConsultation(...) public &#123;    medicalRecord.isFilled = mrtype; // 设置&quot;Yes&quot;/&quot;No&quot;&#125;// 检查病历是否完成function isMedicalRecordFilled(...) public view returns (bool) &#123;    return keccak256(medicalRecord.isFilled) == keccak256(&quot;Yes&quot;);&#125;

该合约完整实现了患者档案管理、挂号预约、电子病历三大核心功能，构建了医疗数据上链的基础框架。

合约结构在 Solidity 中，合约类似于面向对象编程语言中的类。 每个合约中可以包含 状态变量， 函数， 函数修饰器， 事件， 错误， 结构类型 和 枚举类型 的声明，且合约可以从其他合约继承。
还有一些特殊种类的合约，叫做 库合约 和 接口合约。
在关于 合约 的部分包含比本节更多的细节，它的作用是提供一个快速的概述。
状态变量状态变量是指其值被永久地存储在合约存储中的变量。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity &gt;=0.4.0 &lt;0.9.0;contract SimpleStorage &#123;    uint storedData; // 状态变量    // ...&#125;

有效的状态变量类型请参阅 类型 章节， 对状态变量可见性的可能选择请参阅 可见性和 getter 函数。
函数函数是代码的可执行单位。 通常在合约内定义函数，但它们也可以被定义在合约之外。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity &gt;=0.7.1 &lt;0.9.0;contract SimpleAuction &#123;    function bid() public payable &#123; // 函数        // ...    &#125;&#125;// 定义在合约之外的辅助函数function helper(uint x) pure returns (uint) &#123;    return x * 2;&#125;

函数调用 可以发生在内部或外部， 并且对其他合约有不同程度的 可见性。 函数 接受参数并返回变量，以便在它们之间传递参数和值。
函数修饰器函数修饰器可以被用来以声明的方式修改函数的语义(见合约部分的 函数修饰器)。
重写，也就是具有同一个修饰器的名字但有不同的参数，是不可能的。
与函数一样，修饰器也可以被 重写。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity &gt;=0.4.22 &lt;0.9.0;contract Purchase &#123;    address public seller;    modifier onlySeller() &#123; // 修饰器        require(            msg.sender == seller,            &quot;Only seller can call this.&quot;        );        _;    &#125;    function abort() public view onlySeller &#123; // 修饰器的使用        // ...    &#125;&#125;

事件事件是能方便地调用以太坊虚拟机日志功能的接口。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity ^0.8.22;event HighestBidIncreased(address bidder, uint amount); // 事件contract SimpleAuction &#123;    function bid() public payable &#123;        // ...        emit HighestBidIncreased(msg.sender, msg.value); // 触发事件    &#125;&#125;

有关如何声明事件和如何在 dapp 中使用事件的信息，参阅合约章节中的 事件。
错误错误(类型)允许您为失败情况定义描述性的名称和数据。 错误(类型)可以在 回滚声明 中使用。 与字符串描述相比，错误(类型)要便宜得多，并允许您对额外的数据进行编码。 您可以使用 NatSpec 格式来向用户描述错误。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity ^0.8.4;/// 没有足够的资金用于转账。要求 `requested`。/// 但只有 `available` 可用。error NotEnoughFunds(uint requested, uint available);contract Token &#123;    mapping(address =&gt; uint) balances;    function transfer(address to, uint amount) public &#123;        uint balance = balances[msg.sender];        if (balance &lt; amount)            revert NotEnoughFunds(amount, balance);        balances[msg.sender] -= amount;        balances[to] += amount;        // ...    &#125;&#125;

更多信息请参阅合约章节中的 错误和恢复语句。
结构类型结构类型是可以将几个变量分组的自定义类型（参阅类型章节中的 结构体）。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity &gt;=0.4.0 &lt;0.9.0;contract Ballot &#123;    struct Voter &#123; // 结构        uint weight;        bool voted;        address delegate;        uint vote;    &#125;&#125;

枚举类型枚举可用来创建由一定数量的’常量值’构成的自定义类型（参阅类型章节中的 枚举类型）。
open in Remix
// SPDX-License-Identifier: GPL-3.0pragma solidity &gt;=0.4.0 &lt;0.9.0;contract Purchase &#123;    enum State &#123; Created, Locked, Inactive &#125; // 枚举&#125;
